<?php $rows=$service->assets($q,$status); ?>
<div class="toolbar"><form class="filters" method="get"><input type="hidden" name="page" value="assets"><label class="sr-only" for="q">Buscar ativo</label><input id="q" name="q" value="<?= e($q) ?>" placeholder="Buscar serial, modelo, patrimônio ou pessoa"><label class="sr-only" for="status">Status</label><select id="status" name="status"><option value="">Todos os status</option><option value="disponivel" <?= $status==='disponivel'?'selected':'' ?>>Disponíveis</option><option value="emprestado" <?= $status==='emprestado'?'selected':'' ?>>Emprestados</option></select><button class="secondary">Filtrar</button></form><div class="actions"><a class="button secondary" href="<?= e(url('export',['kind'=>'assets','q'=>$q,'status'=>$status])) ?>">Exportar Excel</a><a class="button" href="<?= e(url('asset-form')) ?>">+ Novo ativo</a></div></div>
<section class="card"><div class="section-head"><h2>Equipamentos <small><?= count($rows) ?> registros</small></h2></div><div class="table-wrap"><table><thead><tr><th>Equipamento / serial</th><th>Empresa / patrimônio</th><th>Status</th><th>Colaborador / setor</th><th>Chamado</th><th>Ações</th></tr></thead><tbody>
<?php foreach($rows as $a): ?><tr><td><strong><?= e($a['tipo'].' '.$a['marca'].' '.$a['modelo']) ?></strong><small><?= e($a['serial_number']) ?></small></td><td><?= e($a['empresa']) ?><small><?= e($a['patrimonio']?:'Sem patrimônio') ?></small></td><td><span class="badge <?= $a['at_status']==='disponivel'?'green':'amber' ?>"><?= $a['at_status']==='disponivel'?'Disponível':'Emprestado' ?></span></td><td><?= e($a['colaborador']?:'—') ?><small><?= e($a['setor']) ?></small></td><td>#<?= e($a['id_chamado']) ?></td><td><div class="actions"><a href="<?= e(url('asset-form',['serial'=>$a['serial_number']])) ?>">Editar</a><form method="post" data-confirm="Excluir este ativo? Ativos com histórico de empréstimos serão preservados."><?= csrf() ?><input type="hidden" name="action" value="asset-delete"><input type="hidden" name="serial_number" value="<?= e($a['serial_number']) ?>"><button class="link danger">Excluir</button></form></div></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="6" class="empty">Nenhum ativo encontrado. Cadastre um equipamento para começar.</td></tr><?php endif ?></tbody></table></div></section>
